# Receipt Bot verifier (rb.py v17)

Save the code below exactly as `~/receipt-bot/rb.py`, `chmod +x`, run `RB_TZ={owner IANA zone} python3 ~/receipt-bot/rb.py selftest`; `SELFTEST OK` is the gate. SHA-256 `0b4e51bd295845522336f59a8c1d8827f2c873e9d799942aa5e12bcc46aded5d`; if it differs but selftest passes, tell the owner once.

Verdicts: OK; REJECT (reason); WITHHELD (never verified, proof or shared); RETRY (pending, or a shape change); DUPLICATE, PREVIOUSLY_*; HOUSEKEEPING (not filed); NEED_FULL_ID; NO_RECEIPT_FOUND. OK: the verify API agrees, your SHA-256 of `canonical_bytes` equals `output_hash`, tool and provenance match. `workflow` checks workflow and handover links (Merkle root, steps, sources) and reports `client_decision` and not checked / not run / not proven. `fetch --paste` accepts only the exact JSON.

Never checked: issuer and anchor signatures, final output hash, truncation, whether the goal succeeded, bytes behind redacted handover copies. `sweep`/`fetch` exit 3 (PARSE_ERROR) on anything but one readable page and `commit` keeps the watermark; `doctor` exits 4 when the timeline reads 0 events but the feed shows team receipts. Never edit verdict or parsing logic to pass; if all fails after a zambo.dev change, file nothing and tell the owner.

```python
"""Zambo Receipt Bot verifier (v17 compact; AER-1 -26 merkle_version). Stdlib only; plain web requests to zambo.dev, no Zambo quota.
rb.py selftest | intake [--ws W --bot B --what T --tier b|c] TEXT | sweep PAGE... | digest | commit | since [--set TS]
rb.py crosscheck [--since TS] | doctor [--since TS] PAGE... | workflow [--ws --bot --what --parent WID] TEXT (workflow or handover links) | week [--days N] | features
rb.py fetch --job ID [--since TS] [--date D] (nightly read: direct JSON-RPC to zambo.dev/mcp, saves pages/D-pN.txt) | fetch --paste FILE|- [--date D] (fallback: strict check of the flattened tool text)
rb.py sync [--force] (weekly drift check, free GETs) | offer [limit|seal] (once-a-day Day Pass gate) | hostatus TEXT (client Accept/Flag from public JSON)
Env: RB_DIR (~/receipt-bot), RB_TZ (IANA zone). Verified = saved bytes unchanged since Zambo saved them; not that the answer is right.""";import base64,csv,hashlib,html,json,os,re,sys,time,urllib.error,urllib.parse,urllib.request;from datetime import datetime,timedelta,timezone
try:
 from zoneinfo import ZoneInfo
except ImportError:
 ZoneInfo=None
DIR=os.path.expanduser(os.environ.get('RB_DIR','~/receipt-bot'));LEDGER,STATE=os.path.join(DIR,'ledger.csv'),os.path.join(DIR,'state.json');TZ=os.environ.get('RB_TZ','UTC');COLS=['id','status','created_at','local','workstream','bot','tool','what','tier','checks','reason','run_url','filed_at','reported','caller_id'];HOUSE={'new_session','capability_search','day_pass_status','day_pass_activate','day_pass_checkout_link','workflow_close','workflow_seal','handover','handover_status','handover_list','zambo_home','continuity_get_recent','continuity_list_threads','continuity_open_thread','continuity_set_prefs','continuity_start_thread','pass_status','activity_today','memory_remember','memory_recall','spend_limit_set','spend_limit_status','handover_accept','day_pass_redeem'};QUOTA=re.compile(r'free (daily )?limit|limit (reached|hit|exceeded)|quota|rate.?limit|circuit breaker|too many requests',re.I);BREAKER=re.compile(r'circuit breaker',re.I);TIER=None;TIERS={'b':' (re-observed: corroborates the claim)','c':' (logged claim, not independently verified)','LOGGED BY AGENT':' (logged claim, not independently verified)'}
def _kind(msg,default):
 return 'CIRCUIT_BREAKER' if BREAKER.search(msg)else 'QUOTA_OR_LIMIT' if QUOTA.search(msg)else default
class PageError(Exception):
 """A saved Zambo page that cannot be read exactly. Never treated as 'nothing new'."""
U=r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}';URL=re.compile(r"(?:https?://|www\.)?[A-Za-z0-9.\-@:]*[A-Za-z0-9\-]\.[A-Za-z]{2,}(?::\d+)?/[^\s<>\"'`)\]]*?("+U+r')',re.I);SHORT=re.compile(r"(?i)(?:\b(?:receipt|run|id)|#)\W{0,3}(?<![0-9A-Za-z])([0-9a-f]{8})(?![0-9A-Za-z-])");BARE=re.compile(r'(?<![0-9A-Za-z/-])('+U+r')(?![0-9A-Za-z-])');INJECT=re.compile(r'ignore (all |your |previous )?(rules|instructions)|mark (this )?as verified|pre-?approved|system prompt',re.I);UA={'User-Agent':'zambo-receipt-bot/2','Accept':'application/json'}
def _zone():
 if TZ=='UTC':return timezone.utc
 if not ZoneInfo:sys.exit(f"rb.py: RB_TZ={TZ!r} needs Python 3.9+ zoneinfo; refusing to label times in the wrong zone")
 try:return ZoneInfo(TZ)
 except Exception:sys.exit(f"rb.py: unknown timezone RB_TZ={TZ!r}; use an IANA name like America/New_York")
def local(iso):
 try:dt=datetime.fromisoformat(str(iso).replace('Z','+00:00'))
 except ValueError:return f"{iso} (unparsed time)"
 if dt.tzinfo is None:dt=dt.replace(tzinfo=timezone.utc)
 dt=dt.astimezone(_zone());return f"{dt:%Y-%m-%d} {dt.hour % 12 or 12}:{dt:%M %p} "+(dt.tzname()or 'UTC')
def extract(text):
 out,seen=[],set()
 for m in URL.finditer(text):
  raw=m.group(0);host=re.sub(r':(443|80)$','',urllib.parse.urlsplit(raw if '://' in raw else 'https://'+raw).netloc.lower());rid=m.group(1).lower();bad=None if host in('zambo.dev','www.zambo.dev')else f"foreign or lookalike host {host!r}; not fetched"
  if not bad and not re.search(r'/(run|receipts)/'+U+r'$|/api/v2/receipt/'+U,raw,re.I):
   continue
  if(rid,bad)not in seen:
   seen.add((rid,bad));out.append((rid,bad))
 stripped=URL.sub(' ',text)
 for m in BARE.finditer(stripped):
  rid=m.group(1).lower()
  if(rid,None)not in seen:
   seen.add((rid,None));out.append((rid,None))
 full={i for i,_ in out}
 for m in SHORT.finditer(BARE.sub(' ',stripped)):
  p=m.group(1).lower()
  if not any(f.startswith(p)for f in full)and('short:'+p,None)not in seen:
   seen.add(('short:'+p,None));out.append(('short:'+p,None))
 return out
def resolve_short(p,fetch=None):
 st,body=(fetch or get)(f"https://zambo.dev/api/receipts/recent?format=v2&id_prefix={p}")
 if st==404:return None,'NEED_FULL_ID',f"no receipt starts with {p}; ask for the full link"
 if st!=200:return None,'RETRY',f"id_prefix lookup HTTP {st}"
 try:o=json.loads(body)
 except ValueError:return None,'RETRY','id_prefix lookup returned non-JSON'
 rid=o.get('id')if isinstance(o,dict)else None
 if not(isinstance(rid,str)and re.fullmatch(U,rid)and rid.lower().startswith(p)):
  return None,'NEED_FULL_ID',f"id_prefix lookup for {p} returned an unexpected shape; ask for the full link"
 return rid.lower(),None,'resolved from short id'
def get(url,tries=3):
 for i in range(tries):
  try:
   with urllib.request.urlopen(urllib.request.Request(url,headers=UA),timeout=20)as r:
    return r.status,r.read()
  except urllib.error.HTTPError as e:
   if e.code in(404,410,400):
    return e.code,e.read()
   ra=(e.headers.get('Retry-After')or '0').strip()if e.code in(429,503)else '0';wait=min(int(ra),60)if ra.isdigit()else 5;last=e.code
  except Exception as e:
   wait,last=0,type(e).__name__
  time.sleep(max(wait,2**i))
 return None,str(last).encode()
def check(d,rid,fetch=get):
 if not isinstance(d,dict)or not isinstance(d.get('receipt'),dict)or not isinstance(d.get('checks'),dict)or 'canonical_bytes' not in d['receipt']:
  return 'RETRY',['unexpected verify response shape (zambo.dev may have changed); filed as pending, not judged'],{}
 r,why,ok,notes=d['receipt'],[],[],[]
 if str(d.get('id','')).lower()!=rid or str(r.get('id','')).lower()!=rid:why.append('id mismatch')
 if r.get('canonical_bytes_withheld_for_privacy')is True and not r.get('canonical_bytes'):
  why+=[f"{k} failed" for k,v in d['checks'].items()if isinstance(v,dict)and v.get('status')=='fail']
  if d.get('verification_status')not in('not_checked','withheld','verified'):why.append(f"verification_status={d.get('verification_status')}")
  if CTRL.search(str(r.get('provenance_class')or '')):why.append('provenance label has control characters (AER-1 Section 5)')
  tool=(r.get('tool')or{}).get('name')if isinstance(r.get('tool'),dict)else r.get('tool');caller=r.get('caller')if isinstance(r.get('caller'),dict)else{};info={'tool':tool,'created_at':r.get('created_at'),'prov':r.get('provenance_class'),'checks':', '.join(k for k,v in d['checks'].items()if isinstance(v,dict)and v.get('status')=='pass'),'notes':'canonical bytes withheld by Zambo for privacy; hash not recomputed, not checkable','label':caller.get('label'),'caller_id':caller.get('id')or '','inject':False,'free_remaining':r.get('free_remaining'),'output_hash':r.get('output_hash')};return('REJECT' if why else 'WITHHELD'),why,info
 if d.get('verification_status')!='verified':why.append(f"verification_status={d.get('verification_status')}")
 checks=d.get('checks')or{}
 for k,v in checks.items():
  if isinstance(v,dict)and v.get('status')=='fail':why.append(f"{k} failed")
  elif isinstance(v,dict)and v.get('status')=='pass':ok.append(k)
 if(checks.get('commitment_matches')or{}).get('status')!='pass':why.append('commitment_matches not pass')
 committed={}
 try:
  raw=base64.b64decode(r['canonical_bytes'],validate=True)
  if 'sha256:'+hashlib.sha256(raw).hexdigest()!=r.get('output_hash'):why.append('my SHA-256 of canonical_bytes != output_hash')
  else:ok.append('hash recomputed')
  committed=json.loads(raw)
  if not isinstance(committed,dict):why.append('canonical_bytes is not a JSON object');committed={}
 except(ValueError,TypeError,base64.binascii.Error):
  why.append('canonical_bytes missing or undecodable')
 tool=(r.get('tool')or{}).get('name')if isinstance(r.get('tool'),dict)else r.get('tool');ctool=committed.get('tool')if isinstance(committed.get('tool'),dict)else{}
 if committed and ctool.get('name')!=tool:why.append('tool in bytes != tool in metadata')
 ic=committed.get('issuer_claims')if isinstance(committed.get('issuer_claims'),dict)else{};prov=ic.get('provenance_class')
 if committed and prov!=r.get('provenance_class'):why.append('provenance in bytes != metadata')
 if CTRL.search(str(r.get('provenance_class')or '')):why.append('provenance label has control characters (AER-1 Section 5)')
 env=(r.get('anchor')or{}).get('envelope')if isinstance(r.get('anchor'),dict)else None
 if isinstance(env,dict):
  if str(env.get('receipt_uuid','')).lower()==rid and env.get('output_sha256')==r.get('output_hash'):ok.append('anchor envelope matches')
  else:notes.append('anchor envelope does not match this receipt (anchor not checked)')
 ev,eu=r.get('evidence_sha256'),r.get('evidence_url')or ''
 if ev:
  path=urllib.parse.urlsplit(eu).path if urllib.parse.urlsplit(eu).netloc in('','zambo.dev','www.zambo.dev')else ''
  if path.startswith('/api/evidence/'):
   st,body=fetch('https://zambo.dev'+path)
   if st==200 and 'sha256:'+hashlib.sha256(body).hexdigest()==ev:ok.append('evidence matched')
   elif st==200:why.append('evidence bytes do not match evidence_sha256')
   else:notes.append(f"evidence not fetched (HTTP {st}), not checked")
  else:notes.append(f"evidence url {eu!r} not on zambo.dev, not checked")
 text=json.dumps(committed.get('output',''))[:4000];caller=r.get('caller')if isinstance(r.get('caller'),dict)else{};info={'tool':tool,'created_at':r.get('created_at'),'prov':prov,'checks':', '.join(ok),'notes':'; '.join(notes),'label':caller.get('label'),'caller_id':caller.get('id')or '','inject':bool(INJECT.search(text)),'free_remaining':r.get('free_remaining'),'output_hash':r.get('output_hash')};return('REJECT' if why else 'OK'),why,info
def verify(rid,fetch=get):
 st,body=fetch(f"https://zambo.dev/api/v2/receipt/{rid}/verify")
 if st in(404,410):return 'REJECT',[f"HTTP {st}: receipt does not exist"],{}
 if st!=200:return 'RETRY',[f"verify unreachable or HTTP {st}; retry next run"],{}
 try:d=json.loads(body)
 except ValueError:return 'RETRY',['non-JSON verify response'],{}
 return check(d,rid,fetch)
CTRL=re.compile(r'[\x00-\x1f\x7f]');HO_URL=re.compile(r'zambo\.dev(?::443)?/handover/('+U+r')',re.I);WF_URL=re.compile(r"(?:https?://)?(?:www\.)?zambo\.dev(?::443)?/(?:api/)?workflow/("+U+r')',re.I);NOT_CHECKED=['issuer signature (Zambo publishes no signing key; issuer_authenticated is false)','external anchor (not fetched)','final workflow output hash (none published)','truncation: a shorter rebuilt list would also match (AER-1 8.4; no prior commitment)','that the goal succeeded or the answers are right'];USE={'continuity_get_recent','workflow_close','workflow_seal','handover','handover_status','zambo_home','day_pass_checkout_link','day_pass_status','pass_status','activity_today'};BASE=USE|{'new_session','capability_search','continuity_list_threads','continuity_open_thread','continuity_set_prefs','continuity_start_thread','credithunt','day_pass_activate','ghost_audit_report','ghost_audit_site','ghost_audit_status','journal_log','leadsignal','live_price','pdf_extract','prompt_shield','provibe_audit','zambo_universal','handover_list','handover_accept','memory_remember','memory_recall','spend_limit_set','spend_limit_status','day_pass_redeem'}
MERKLE_VERSIONS=('receipt-id-v0','seq-output-v1')
def merkle(ids,version='receipt-id-v0',hashes=None):
 # AER-1 Section 8.1: receipt-id-v0 leaf = receipt id; seq-output-v1 leaf = "<seq>:<output_hash hex>", seq 1-based
 if version=='seq-output-v1':leaves=[f"{n+1}:{str(h).lower().removeprefix('sha256:')}"for n,h in enumerate(hashes or[])]
 else:leaves=list(ids)
 lv=[hashlib.sha256(i.encode('utf-8')).digest()for i in leaves]
 if not lv:return ''
 while len(lv)>1:
  if len(lv)%2:lv.append(lv[-1])
  lv=[hashlib.sha256(lv[i]+lv[i+1]).digest()for i in range(0,len(lv),2)]
 return lv[0].hex()
def workflow(wid,fetch=get):
 cache={}
 def cf(u):
  if u not in cache:cache[u]=fetch(u)
  return cache[u]
 out={'workflow_id':wid,'workflow_url':f"https://zambo.dev/workflow/{wid}",'checked':[],'not_checked':list(NOT_CHECKED),'steps':[]};st,body=cf(f"https://zambo.dev/api/workflow/{wid}")
 if st in(404,410):return{**out,'verdict':'REJECT','reasons':[f"HTTP {st}: workflow not published (missing or expired)"]}
 if st!=200:return{**out,'verdict':'RETRY','reasons':[f"workflow view unreachable or HTTP {st}; retry next run"]}
 try:v=json.loads(body)
 except ValueError:return{**out,'verdict':'RETRY','reasons':['non-JSON workflow view']}
 rs=v.get('receipts')if isinstance(v,dict)else None
 if not isinstance(rs,list)or not isinstance(v.get('merkle_root'),str)or not all(isinstance(x,dict)for x in rs):
  return{**out,'verdict':'RETRY','reasons':['unexpected workflow view shape (zambo.dev may have changed); not judged']}
 why,retry,held=[],[],[]
 if wid not in(str(v.get('id','')).lower(),str(v.get('workflow_id','')).lower(),str(v.get('session_workflow_id','')).lower()):
  why.append('workflow id mismatch')
 real=str(v.get('workflow_id')or wid).lower();out.update(workflow_id=real,workflow_url=f"https://zambo.dev/workflow/{real}");ids=[str(x.get('id','')).lower()for x in rs]
 if not ids:why.append('workflow has no steps')
 if len(set(ids))!=len(ids):why.append('same step receipt listed twice')
 if[x.get('step_index')for x in rs]!=list(range(len(rs))):why.append('step_index not 0..n-1 in order')
 if v.get('count')!=len(rs):why.append(f"count {v.get('count')} != {len(rs)} steps listed")
 mv=v.get('merkle_version')or 'receipt-id-v0'
 if mv not in MERKLE_VERSIONS:return{**out,'verdict':'RETRY','reasons':[f"unknown merkle_version {mv!r} (zambo.dev may have changed); not judged"]}
 if ids and merkle(ids,mv,[x.get('output_hash','')for x in rs])==v['merkle_root'].lower():out['checked'].append(f'Merkle root recomputed ({mv})')
 elif ids:why.append(f'my Merkle root ({mv}) != published merkle_root')
 for x,rid in zip(rs,ids):
  if not re.fullmatch(U,rid):why.append(f"step {rid!r} is not a receipt id");continue
  sv,swhy,info=verify(rid,cf);out['steps'].append({'id':rid,'tool':info.get('tool')or x.get('tool'),'verdict':sv,'run_url':f"https://zambo.dev/run/{rid}",'bot':info.get('label')or 'no bot label','status':str(x.get('status')or '')})
  if sv=='REJECT':why.append(f"step {rid[:8]} rejected: {'; '.join(swhy)}")
  elif sv=='RETRY':retry.append(f"step {rid[:8]}: {'; '.join(swhy)}")
  else:
   if sv=='WITHHELD':held.append(rid[:8])
   if 'sha256:'+str(x.get('output_hash','')).lower()!=str(info.get('output_hash','')).lower():why.append(f"step {rid[:8]} output_hash != its receipt")
   if x.get('tool')and info.get('tool')and x['tool']!=info['tool']:why.append(f"step {rid[:8]} tool != its receipt")
 if ids and not why and not retry and not held:out['checked'].append(f"all {len(ids)} step receipts verified, hashes match")
 cid=str(v.get('closed_receipt_id')or '').lower()
 if re.fullmatch(U,cid):
  cv,cwhy,cinfo=verify(cid,cf)
  if cv=='OK' and cinfo.get('tool')=='workflow_close':
   c=json.loads(base64.b64decode(json.loads(cf(f"https://zambo.dev/api/v2/receipt/{cid}/verify")[1])['receipt']['canonical_bytes']));co=c.get('output')if isinstance(c.get('output'),dict)else{};kids=[(str(k.get('id','')).lower(),str(k.get('output_hash','')).lower())for k in co.get('children')or[]if isinstance(k,dict)]
   if kids==[(i,str(x.get('output_hash','')).lower())for x,i in zip(rs,ids)]and str(co.get('merkle_root','')).lower()==v['merkle_root'].lower():
    out['checked'].append(f"close receipt {cid[:8]} (hash-checked) lists the same steps and root")
   else:why.append(f"close receipt {cid[:8]} lists different steps or root than the workflow page")
  elif cv=='RETRY':retry.append(f"close receipt {cid[:8]}: {'; '.join(cwhy)}")
  elif cv=='OK':why.append(f"closed_receipt_id {cid[:8]} is a {cinfo.get('tool')} receipt, not workflow_close")
  else:why.append(f"close receipt {cid[:8]} {cv}: {'; '.join(cwhy)}")
 else:out['not_checked'].insert(0,'close receipt (none listed)')
 verdict='REJECT' if why else 'RETRY' if retry else 'WITHHELD' if held else 'OK';bots={}
 for k in out['steps']:bots[k['bot']]=bots.get(k['bot'],0)+1
 failed=[n for n,k in enumerate(out['steps'])if k['status']not in('success','ok','')];retried=[n for n in failed if any(k['tool']==out['steps'][n]['tool']and k['status']in('success','ok')for k in out['steps'][n+1:])];out.update(bots=bots,failed_steps=len(failed),retried_steps=len(retried),session_workflow_id=str(v.get('session_workflow_id')or '').lower(),last_at=v.get('last_at')or '')
 if held:out['not_checked'].insert(0,f"withheld steps {', '.join(held)} (bytes withheld by Zambo)")
 out.update(verdict=verdict,reasons=why+retry,count=len(ids),merkle_root=v['merkle_root'].lower(),closed_receipt_id=cid,created_at=v.get('first_at')or '',sealed=bool(v.get('sealed')));return out
def handover(hid,fetch=get):
 st,b=fetch(f'https://zambo.dev/handover/{hid}.json');url=f'https://zambo.dev/handover/{hid}'
 if st in(404,410):return{'workflow_id':hid,'workflow_url':url,'verdict':'REJECT','reasons':[f'HTTP {st}: handover not published'],'checked':[],'not_checked':list(NOT_CHECKED),'steps':[]}
 try:h=json.loads(b)if st==200 else None
 except ValueError:h=None
 if not isinstance(h,dict)or not re.fullmatch(U,str(h.get('workflow_id',''))):
  return{'workflow_id':hid,'workflow_url':url,'verdict':'RETRY','reasons':[f'handover unreachable or unexpected shape (HTTP {st})'],'checked':[],'not_checked':list(NOT_CHECKED),'steps':[]}
 r=workflow(h['workflow_id'].lower(),fetch);why,n=[],0
 for x in h.get('steps')or[]:
  try:raw=base64.b64decode(x.get('canonical_bytes_base64')or '',validate=True)
  except(ValueError,base64.binascii.Error):raw=None
  if raw is None or 'sha256:'+hashlib.sha256(raw).hexdigest()!=x.get('output_hash'):why.append(f"handover copy {str(x.get('id'))[:8]} bytes != its hash")
  src=str(x.get('source_receipt_id')or '').lower()
  if src:
   sv,swhy,si=verify(src,fetch);n+=1
   if sv=='RETRY':r['verdict']='RETRY' if r['verdict']=='OK' else r['verdict']
   elif sv not in('OK','WITHHELD'):why.append(f'source receipt {src[:8]} {sv}')
   elif si.get('tool')!=x.get('tool'):why.append(f'source receipt {src[:8]} tool != copy')
 if why:r['verdict']='REJECT';r['reasons']=r.get('reasons',[])+why
 elif r['verdict']=='OK':r['checked'].append(f'{n} source receipts verified, every copy hash-matches')
 r.update(handover_url=url,recipient=h.get('recipient'),goal=h.get('goal'),client_decision=h.get('status'),decided_at=h.get('decided_at'),handover_not_checked=h.get('not_checked')or[],handover_not_run=h.get('not_run')or[],handover_not_proven=h.get('not_proven')or[]);r['not_checked'].append('handover steps are redacted copies (LOGGED BY AGENT) of the source receipts');return r
def features(fetch=None):
 req=urllib.request.Request('https://zambo.dev/mcp',data=b'{"jsonrpc":"2.0","id":1,"method":"tools/list"}',headers={**UA,'Content-Type':'application/json','Accept':'application/json, text/event-stream'})
 try:
  with urllib.request.urlopen(req,timeout=20)as f:names={t['name']for t in json.loads(f.read())['result']['tools']}
 except Exception as e:return{'verdict':'RETRY','reasons':[f'tools/list unreachable: {type(e).__name__}']}
 return{'live':sorted(names&USE),'missing':sorted(USE-names),'new':sorted(names-BASE),'count':len(names)}
MCP='https://zambo.dev/mcp'
def _rpc_body(raw,ctype=''):
 t=raw.decode('utf-8','replace')if isinstance(raw,bytes)else str(raw)
 if 'event-stream' in ctype or t.lstrip().startswith(('event:','data:','id:')):
  msgs=[]
  for blk in re.split(r'\r?\n\r?\n',t):
   d='\n'.join(l[5:].lstrip()for l in blk.splitlines()if l.startswith('data:'))
   if d.strip():
    try:m=json.loads(d)
    except ValueError:return None
    if isinstance(m,dict)and('result' in m or 'error' in m):msgs.append(m)
